// Writes test/fixtures/js-web/Wpt.lean: test data of web-platform-tests (WPT)
// at a pinned commit, as JSON string literals the conformance program
// (test/fixtures/js-web/Main.lean) parses with JSON.parse. WPT is under the
// 3-Clause BSD License (its LICENSE.md, quoted in the generated file).
//
//   node scripts/bindings/wpt-data.mjs [--check]
//
// Data taken: url/resources/urltestdata.json (the URL parser's cases),
// url/urlencoded-parser.any.js (its array of application/x-www-form-urlencoded
// cases) and encoding/textdecoder-fatal.any.js (its `bad` UTF-8 sequences).
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';

const commit = '8c17bfeb3e66a2986be16b0e004f85ace68db647'; // 2026-11-07
const base = `https://raw.githubusercontent.com/web-platform-tests/wpt/${commit}/`;
const target = fileURLToPath(new URL('../../test/fixtures/js-web/Wpt.lean', import.meta.url));
const get = async path => {
  const response = await fetch(base + path);
  if (!response.ok) throw new Error(`${path}: HTTP ${response.status}`);
  return response.text();
};
// The array literals are evaluated alone, in an empty context: they are data.
const literal = (source, from, to) => {
  const start = source.indexOf(from), end = source.indexOf(to, start);
  if (start < 0 || end < 0) throw new Error(`cannot find ${from}…${to}`);
  return vm.runInNewContext(`(${source.slice(start + from.length - 1, end + 1)})`, Object.create(null), { timeout: 1000 });
};

const urls = JSON.parse(await get('url/resources/urltestdata.json')).filter(c => typeof c === 'object');
const urlencoded = literal(await get('url/urlencoded-parser.any.js'), '[', '].forEach');
const fatal = literal(await get('encoding/textdecoder-fatal.any.js'), 'var bad = [', '];').filter(c => c.encoding === 'utf-8');
const license = (await get('LICENSE.md')).trim();

const raw = text => {
  let hashes = '#';
  while (text.includes('"' + hashes)) hashes += '#';
  return `r${hashes}"${text}"${hashes}`;
};
const lean = `/-
GENERATED by scripts/bindings/wpt-data.mjs from web-platform-tests at commit
${commit}; do not edit.
${license.replace(/-\//g, '- /')}
-/
namespace Wpt

/-- url/resources/urltestdata.json: the URL parser's test cases (comments removed). -/
def urlTestData : String := ${raw(JSON.stringify(urls))}

/-- url/urlencoded-parser.any.js: application/x-www-form-urlencoded inputs and their name-value pairs. -/
def urlencodedParser : String := ${raw(JSON.stringify(urlencoded))}

/-- encoding/textdecoder-fatal.any.js: invalid UTF-8 sequences (the utf-8 entries of \`bad\`). -/
def textDecoderFatal : String := ${raw(JSON.stringify(fatal))}

end Wpt
`;
if (process.argv.includes('--check')) {
  if (!existsSync(target) || readFileSync(target, 'utf8') !== lean) { console.error(`${target} is stale`); process.exit(1); }
  console.log('Wpt.lean is up to date');
} else {
  writeFileSync(target, lean);
  console.log(`wrote ${target}: ${urls.length} URL cases, ${urlencoded.length} urlencoded cases, ${fatal.length} invalid UTF-8 sequences`);
}
